<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage1; use Aws\S3\Exception\S3Exception as S3; class aws_s3 extends cloudStorage1 { var $access_key_id; var $secret_access_key; var $region; public function init() { $this->custom_upload_dir = $this->options->cloud_storage_aws_s3_custom_upload_dir; $this->protocol = $this->options->cloud_storage_aws_s3_protocol; $this->host = $this->options->cloud_storage_aws_s3_host; $this->folder = $this->options->cloud_storage_aws_s3_folder; $this->access_key_id = trim($this->options->cloud_storage_aws_s3_access_key_id); $this->secret_access_key = trim($this->options->cloud_storage_aws_s3_secret_access_key); $this->region = $this->options->cloud_storage_aws_s3_region; $this->bucket = trim($this->options->cloud_storage_aws_s3_bucket); $this->cloud_thumbnail = false; $this->silent_scanning = $this->options->cloud_storage_aws_s3_silent_scanning; $this->auto_replace = $this->options->cloud_storage_aws_s3_auto_replace; $this->sync_delete = $this->options->cloud_storage_aws_s3_sync_delete; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_aws_s3_delete_attachment_after_synced; $this->sync_the_website_resource = $this->options->cloud_storage_aws_s3_sync_the_website_resource; $this->website_resource_filetypes = $this->options->cloud_storage_aws_s3_website_resource_filetypes; $this->custom_replacement = $this->options->cloud_storage_aws_s3_custom_replacement; } public function includes() { if ( !class_exists('Aws\S3\Exception\S3Exception') ) require 'phar://'.WP_CONTENT_DIR.'/libs/aws.phar'; } public function access_service() { if ($this->enabled && $this->is_current && !$this->accessed) { $this->includes(); list($this->accessed, $this->client) = apply_filters( 'qqworld-collector-cloud-storage-aws-s3-access-service', array(false, null), $this->region, $this->access_key_id, $this->secret_access_key ); } } public function is_object_exist($destination_path) { $destination_path = preg_replace('/^\/*/i', '', $destination_path); $this->access_service(); return $this->client->doesObjectExist($this->bucket, $destination_path); } public function upload($destination_path, $source_path) { $this->access_service(); try { if ($this->is_object_exist($destination_path)) { if ($this->options->cloud_storage_override) { $this->delete_object($destination_path); } else { return true; } } $result = $this->client->putObject([ 'Bucket' => $this->bucket, 'Key' => $destination_path, 'Body' => file_get_contents($source_path) ]); } catch(S3 $e) { return false; do_action( 'qqworld-collector-log', $this->log_id, 'AWS s3:', $e->getMessage() ); } return true; } public function delete_object($object) { $object = preg_replace('/^\/*/i', '', $object); $this->access_service(); try { $result = $this->client->DeleteObject([ 'Bucket' => $this->bucket, 'Key' => $object ]); } catch(S3 $e) { do_action( 'qqworld-collector-log', $this->log_id, 'AWS s3:', $e->getMessage() ); return false; } return true; } public function add_could_storage_form($guid) { if (file_exists(WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'aws.phar')) { $this->access_service(); require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } else { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'-no-sdk.php'; } } public function external_sdk($sdks) { $sdks['cloud-storage']['items']['aws-s3'] = array( 'label' => __('Amazon Web Services S3 Cloud Storage (AWS S3)', $this->text_domain), 'path' => WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'aws.phar', 'download' => 'aws.phar', 'extract' => false, 'manual' => sprintf(__('Please download <a href="%s" target="_blank"><strong>%s</strong></a> and place it in <strong>%s.</strong>', $this->text_domain), 'https://pan.qqworld.org/QQWorld%E6%94%B6%E8%97%8F%E5%AE%B6%E8%B1%AA%E5%8D%8E%E7%89%88/%E8%